@app.route('/')
def index():
    return render_template('index.html')

@app.route('/generate_imagen', methods=['POST'])
def generate_imagen():
    try:
        data = request.get_json()
        prompt = data.get('prompt', '')
        aspect_ratio = data.get('aspect_ratio', '1:1')
        safety_filter_level = data.get('safety_filter_level', 'block_medium_and_above')
        output_format = data.get('output_format', 'png')

        if not prompt:
            return jsonify({'error': 'A szöveg prompt szükséges'}), 400

         Run Google Imagen 4 Ultra model
        output = replicate_client.run(
            "google/imagen4ultra",
            input={
                "prompt": prompt,
                "aspect_ratio": aspect_ratio,
                "safety_filter_level": safety_filter_level,
                "output_format": output_format
            }
        )

         Extract URL from FileOutput object
        if isinstance(output, list) and len(output) > 0:
            image_url = str(output[0])
        elif hasattr(output, 'url'):
            image_url = output.url
        elif isinstance(output, str):
            image_url = output
        else:
            image_url = str(output)

        return jsonify({
            'success': True,
            'image_url': image_url,
            'prompt': prompt,
            'model': 'Google Imagen 4 Ultra'
        })

    except Exception as e:
        return jsonify({'error': f'Hiba történt: {str(e)}'}), 500

@app.route('/generate_flux', methods=['POST'])
def generate_flux():
    try:
        data = request.get_json()
        prompt = data.get('prompt', '')
        aspect_ratio = data.get('aspect_ratio', '1:1')
