        }

        if finetune_id:
            input_data["finetune_id"] = finetune_id
            input_data["finetune_strength"] = finetune_strength

        if seed:
            input_data["seed"] = int(seed)

         Run Flux 1.1 Pro Ultra model
        output = replicate_client.run(
            "blackforestlabs/flux1.1proultrafinetuned",
            input=input_data
        )

         Extract URL from FileOutput object
        if isinstance(output, list) and len(output) > 0:
            image_url = str(output[0])
        elif hasattr(output, 'url'):
            image_url = output.url
        elif isinstance(output, str):
            image_url = output
        else:
            image_url = str(output)

        return jsonify({
            'success': True,
            'image_url': image_url,
            'prompt': prompt,
            'model': 'Flux 1.1 Pro Ultra'
        })

    except Exception as e:
        return jsonify({'error': f'Hiba történt: {str(e)}'}), 500

@app.route('/generate_combined', methods=['POST'])
def generate_combined():
    try:
        data = request.get_json()
        prompt = data.get('prompt', '')
        aspect_ratio = data.get('aspect_ratio', '1:1')

        if not prompt:
            return jsonify({'error': 'A szöveg prompt szükséges'}), 400

        results = []

         Generate with Google Imagen 4 Ultra
        try:
            imagen_output = replicate_client.run(
                "google/imagen4ultra",
                input={
                    "prompt": prompt,
                    "aspect_ratio": aspect_ratio,
                    "safety_filter_level": "block_medium_and_above",
                    "output_format": "png"
                }
            )
             Extract URL from FileOutput object
            if isinstance(imagen_output, list) and len(imagen_output) > 0:
                imagen_url = str(imagen_output[0])
            elif hasattr(imagen_output, 'url'):
                imagen_url = imagen_output.url
            elif isinstance(imagen_output, str):
                imagen_url = imagen_output
            else:
                imagen_url = str(imagen_output)
            results.append({
                'model': 'Google Imagen 4 Ultra',
                'image_url': imagen_url,
                'success': True
            })
        except Exception as e:
            results.append({
                'model': 'Google Imagen 4 Ultra',
                'error': str(e),
                'success': False
            })

         Generate with Flux 1.1 Pro Ultra
        try:
            flux_output = replicate_client.run(
                "blackforestlabs/flux1.1proultrafinetuned",
                input={
                    "prompt": prompt,
                    "aspect_ratio": aspect_ratio,
                    "safety_tolerance": 3
                }
            )
             Extract URL from FileOutput object
            if isinstance(flux_output, list) and len(flux_output) > 0:
                flux_url = str(flux_output[0])
            elif hasattr(flux_output, 'url'):
                flux_url = flux_output.url
            elif isinstance(flux_output, str):
                flux_url = flux_output
            else:
                flux_url = str(flux_output)
            results.append({
                'model': 'Flux 1.1 Pro Ultra',
                'image_url': flux_url,
                'success': True
            })
        except Exception as e:
            results.append({
                'model': 'Flux 1.1 Pro Ultra',
                'error': str(e),
                'success': False
            })

        return jsonify({
            'success': True,
            'prompt': prompt,
            'results': results
        })

    except Exception as e:
        return jsonify({'error': f'Hiba történt: {str(e)}'}), 500

@app.route('/download')
def download_image():
    image_url = request.args.get('url')
    if not image_url:
        return "Nincs kép URL megadva", 400

    try:
        response = requests.get(image_url)
        response.raise_for_status()

        img_io = BytesIO(response.content)
        img_io.seek(0)

        filename = f"generated_image_{uuid.uuid4().hex[:8]}.png"

        return send_file(
            img_io,
            mimetype='image/png',
            as_attachment=True,
            download_name=filename
        )

    except Exception as e:
        return f"Hiba a kép letöltésekor: {str(e)}", 500

if __name__ == '__main__':
    debug_mode = os.environ.get('FLASK_DEBUG', 'False').lower() == 'true'
    app.run(host='0.0.0.0', port=5000, debug=debug_mode)


