            const mainContent = document.getElementById('maincontent');

            // Hide overlay
            overlay.classList.remove('active');

            // Show main content after overlay animation
            setTimeout(() => {
                mainContent.classList.remove('hidden');
            }, 300);
        }

        function showImageGenerator() {
            const mainContent = document.getElementById('maincontent');
            closeBetaMenu();

            // Show the image generator content
            setTimeout(() => {
                mainContent.style.display = 'block';
                mainContent.classList.remove('hidden');
            }, 500);
        }

        function showTab(tabName) {
            // Hide all tabs
            document.querySelectorAll('.tabcontent').forEach(tab => {
                tab.classList.remove('active');
            });
            document.querySelectorAll('.tab').forEach(tab => {
                tab.classList.remove('active');
            });

            // Show selected tab
            document.getElementById(tabName + 'tab').classList.add('active');
            event.target.classList.add('active');
        }

        function showLoading(message = 'Kép generálása folyamatban...') {
            document.getElementById('results').innerHTML = 
                <div class="loading">
                    <div class="spinner"></div>
                    ${message}
                </div>
            ;
        }

        function showError(message) {
            document.getElementById('results').innerHTML = 
                <div class="errormessage">
                    <strong>Hiba:</strong> ${message}
                </div>
            ;
        }

        function showResult(data, endpoint) {
            const resultsDiv = document.getElementById('results');

            if (endpoint === 'generate_combined') {
                let html = '<div class="resultitem"><h3>Generált képek mindkét modellel:</h3>';

                data.results.forEach(result => {
                    if (result.success) {
                        html += 
                            <div class="resultheader">
                                <span class="modelname">${result.model}</span>
                                <a href="/download?url=${encodeURIComponent(result.image_url)}" class="downloadbtn">Letöltés</a>
                            </div>
                            <img src="${result.image_url}" alt="Generált kép  ${result.model}" class="resultimage">
                        ;
                    } else {
                        html += 
                            <div class="resultheader">
                                <span class="modelname">${result.model}</span>
                            </div>
                            <div class="errormessage">Hiba: ${result.error}</div>
                        ;
                    }
                });

                html += '</div>';
                resultsDiv.innerHTML = html;
            } else {
                resultsDiv.innerHTML = 
                    <div class="resultitem">
                        <div class="resultheader">
                            <span class="modelname">${data.model}</span>
                            <a href="/download?url=${encodeURIComponent(data.image_url)}" class="downloadbtn">Letöltés</a>
                        </div>
                        <img src="${data.image_url}" alt="Generált kép" class="resultimage">
                        <p><strong>Prompt:</strong> ${data.prompt}</p>
                    </div>
                ;
            }
        }

        async function generateImage(endpoint, formData) {
            showLoading();

            try {
                const response = await fetch(/${endpoint}, {
                    method: 'POST',
                    headers: {
                        'ContentType': 'application/json',
                    },
                    body: JSON.stringify(formData)
                });

                const data = await response.json();

                if (data.success) {
                    showResult(data, endpoint);
                } else {
                    showError(data.error || 'Ismeretlen hiba történt');
                }
            } catch (error) {
                showError(Hálózati hiba: ${error.message});
            }
        }

        document.getElementById('imagenform').addEventListener('submit', async (e) => {
            e.preventDefault();

            const formData = {
                prompt: document.getElementById('imagenprompt').value,
                aspect_ratio: document.getElementById('imagenaspectratio').value,
                safety_filter_level: document.getElementById('imagensafety').value,
                output_format: 'png'
            };

            await generateImage('generate_imagen', formData);
        });

        document.getElementById('fluxform').addEventListener('submit', async (e) => {
            e.preventDefault();

            const formData = {
                prompt: document.getElementById('fluxprompt').value,
                aspect_ratio: document.getElementById('fluxaspectratio').value,
                finetune_id: document.getElementById('fluxfinetuneid').value,
                finetune_strength: parseFloat(document.getElementById('fluxfinetunestrength').value),
                safety_tolerance: parseInt(document.getElementById('fluxsafety').value)
            };

            const seed = document.getElementById('fluxseed').value;
            if (seed) {
                formData.seed = parseInt(seed);
            }

            await generateImage('generate_flux', formData);
        });

        document.getElementById('combinedform').addEventListener('submit', async (e) => {
            e.preventDefault();

            const formData = {
                prompt: document.getElementById('combinedprompt').value,
                aspect_ratio: document.getElementById('combinedaspectratio').value
            };

            showLoading('Képek generálása folyamatban mindkét modellel...');
            await generateImage('generate_combined', formData);
        });
    </script>
</body>
</html>

