 Modern AI Képgeneráló Platform: Google Cloud Vertex AI és Replicate Integráció

A következő átdolgozás egy korszerű, professzionális megoldást mutat be, amely Google Service Account autentikációt használ a Google Cloud Vertex AI szolgáltatásokhoz, miközben az API kulcsokat biztonságosan tárolja a Replicate secrets rendszerében.

 Korszerű Flask Alkalmazás Architektúra

 Fő Backend Alkalmazás (app.py)

python
import os
import logging
import asyncio
import uuid
import base64
from io import BytesIO
from typing import Dict, List, Optional, Union
from dataclasses import dataclass
from datetime import datetime

from flask import Flask, render_template, request, jsonify, send_file
from google.cloud import aiplatform
from google.auth import load_credentials_from_file
from google.oauth2 import service_account
import replicate
import requests
import json

# Korszerű logging konfiguráció
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(name)s - %(levelname)s - %(message)s',
    handlers=[
        logging.FileHandler('app.log'),
        logging.StreamHandler()
    ]
)
logger = logging.getLogger(__name__)

@dataclass
class GenerationConfig:
    """Képgenerálási konfiguráció adatstruktúra"""
    prompt: str
    aspect_ratio: str = "1:1"
    safety_filter_level: str = "block_medium_and_above"
    output_format: str = "png"
    model_type: str = "imagen"

class ConfigManager:
    """Centralizált konfiguráció kezelő"""

    def __init__(self):
        self.google_project_id = os.environ.get('GOOGLE_CLOUD_PROJECT_ID')
        self.google_location = os.environ.get('GOOGLE_CLOUD_LOCATION', 'us-central1')
        self.service_account_json = os.environ.get('GOOGLE_SERVICE_ACCOUNT_JSON')
        self.replicate_api_token = os.environ.get('REPLICATE_API_TOKEN')

        if not all([self.google_project_id, self.service_account_json, self.replicate_api_token]):
            raise ValueError("Hiányzó környezeti változók: GOOGLE_CLOUD_PROJECT_ID, GOOGLE_SERVICE_ACCOUNT_JSON, REPLICATE_API_TOKEN")

class GoogleCloudImageGenerator:
    """Google Cloud Vertex AI Imagen integráció"""

    def __init__(self, config: ConfigManager):
        self.config = config
        self.credentials = None
        self.client = None
        self._initialize_credentials()

    def _initialize_credentials(self):
        """Service Account hitelesítő adatok inicializálása"""
        try:
            # Service Account JSON betöltése environment változóból
            service_account_info = json.loads(self.config.service_account_json)
            self.credentials = service_account.Credentials.from_service_account_info(
                service_account_info,
                scopes=['https://www.googleapis.com/auth/cloud-platform']
            )

            # Vertex AI inicializálása
            aiplatform.init(
                project=self.config.google_project_id,
                location=self.config.google_location,
                credentials=self.credentials
            )

            logger.info("Google Cloud Vertex AI sikeresen inicializálva")

        except Exception as e:
            logger.error(f"Google Cloud inicializálás hiba: {str(e)}")
            raise

    async def generate_image(self, generation_config: GenerationConfig) -> Dict:
        """Kép generálása Google Imagen 3/4 modellel"""
        try:
            from vertexai.preview.vision_models import ImageGenerationModel

            # Imagen 3 modell betöltése
            model = ImageGenerationModel.from_pretrained("imagen-3.0-generate-001")

            # Generálási paraméterek
            generation_parameters = {
                "number_of_images": 1,
                "aspect_ratio": generation_config.aspect_ratio,
                "safety_filter_level": generation_config.safety_filter_level,
                "person_generation": "allow_adult"
            }

            # Kép generálása
            images = model.generate_images(
                prompt=generation_config.prompt,
                **generation_parameters
            )

            if not images:
                raise ValueError("Nem sikerült képet generálni")

            # Első generált kép feldolgozása
            image = images[0]

            # Kép konvertálása base64 formátumba
            image_bytes = image._image_bytes
            image_base64 = base64.b64encode(image_bytes).decode('utf-8')
            image_url = f"data:image/png;base64,{image_base64}"

            result = {
                'success': True,
                'image_url': image_url,
                'image_bytes': image_bytes,
                'prompt': generation_config.prompt,
                'model': 'Google Imagen 3',
                'generation_time': datetime.now().isoformat(),
                'parameters': generation_parameters
            }

            logger.info(f"Sikeres képgenerálás Google Imagen-nel: {generation_config.prompt[:50]}...")
            return result

        except Exception as e:
            logger.error(f"Google Imagen generálás hiba: {str(e)}")
            return {
                'success': False,
                'error': str(e),
                'model': 'Google Imagen 3'
            }

class ReplicateImageGenerator:
    """Replicate API integráció a Flux modellhez"""

    def __init__(self, api_token: str):
        self.client = replicate.Client(api_token=api_token)

    async def generate_flux_image(self, generation_config: GenerationConfig, **kwargs) -> Dict:
        """Flux 1.1 Pro Ultra képgenerálás"""
        try:
            input_data = {
                "prompt": generation_config.prompt,
                "aspect_ratio": generation_config.aspect_ratio,
                "safety_tolerance": kwargs.get('safety_tolerance', 3)
            }

            # Opcionális paraméterek hozzáadása
            if kwargs.get('finetune_id'):
                input_data["finetune_id"] = kwargs['finetune_id']
                input_data["finetune_strength"] = kwargs.get('finetune_strength', 0.8)

            if kwargs.get('seed'):
                input_data["seed"] = int(kwargs['seed'])

            # Flux modell futtatása
            output = self.client.run(
                "black-forest-labs/flux-1.1-pro-ultra-finetuned",
                input=input_data
            )

            # URL kinyerése
            image_url = self._extract_url(output)

            result = {
                'success': True,
                'image_url': image_url,
                'prompt': generation_config.prompt,
                'model': 'Flux 1.1 Pro Ultra',
                'generation_time': datetime.now().isoformat(),
                'parameters': input_data
            }

            logger.info(f"Sikeres képgenerálás Flux-szal: {generation_config.prompt[:50]}...")
            return result

        except Exception as e:
            logger.error(f"Flux generálás hiba: {str(e)}")
            return {
                'success': False,
                'error': str(e),
                'model': 'Flux 1.1 Pro Ultra'
            }

    def _extract_url(self, output) -> str:
        """URL kinyerése a Replicate válaszból"""
        if isinstance(output, list) and len(output) > 0:
            return str(output[0])
        elif hasattr(output, 'url'):
            return output.url
        elif isinstance(output, str):
            return output
        else:
            return str(output)

class ImageGeneratorApp:
    """Fő alkalmazás osztály"""

    def __init__(self):
        self.app = Flask(__name__)
        self.config = ConfigManager()
        self.google_generator = GoogleCloudImageGenerator(self.config)
        self.replicate_generator = ReplicateImageGenerator(self.config.replicate_api_token)
        self._setup_routes()

    def _setup_routes(self):
        """Flask útvonalak beállítása"""

        @self.app.route('/')
        def index():
            return render_template('index.html')

        @self.app.route('/generate_imagen', methods=['POST'])
        async def generate_imagen():
            try:
                data = request.get_json()

                generation_config = GenerationConfig(
                    prompt=data.get('prompt', ''),
                    aspect_ratio=data.get('aspect_ratio', '1:1'),
                    safety_filter_level=data.get('safety_filter_level', 'block_medium_and_above'),
                    output_format=data.get('output_format', 'png')
                )

                if not generation_config.prompt:
                    return jsonify({'error': 'A szöveg prompt szükséges'}), 400

                result = await self.google_generator.generate_image(generation_config)

                if result['success']:
                    return jsonify(result)
                else:
                    return jsonify(result), 500

            except Exception as e:
                logger.error(f"Imagen endpoint hiba: {str(e)}")
                return jsonify({'error': f'Szerver hiba: {str(e)}'}), 500

        @self.app.route('/generate_flux', methods=['POST'])
        async def generate_flux():
            try:
                data = request.get_json()

                generation_config = GenerationConfig(
                    prompt=data.get('prompt', ''),
                    aspect_ratio=data.get('aspect_ratio', '1:1')
                )

                if not generation_config.prompt:
                    return jsonify({'error': 'A szöveg prompt szükséges'}), 400

                flux_params = {
                    'finetune_id': data.get('finetune_id', ''),
                    'finetune_strength': data.get('finetune_strength', 0.8),
                    'safety_tolerance': data.get('safety_tolerance', 3),
                    'seed': data.get('seed')
                }

                result = await self.replicate_generator.generate_flux_image(
                    generation_config, **flux_params
                )

                if result['success']:
                    return jsonify(result)
                else:
                    return jsonify(result), 500

            except Exception as e:
                logger.error(f"Flux endpoint hiba: {str(e)}")
                return jsonify({'error': f'Szerver hiba: {str(e)}'}), 500

        @self.app.route('/generate_combined', methods=['POST'])
        async def generate_combined():
            try:
                data = request.get_json()

                generation_config = GenerationConfig(
                    prompt=data.get('prompt', ''),
                    aspect_ratio=data.get('aspect_ratio', '1:1')
                )

                if not generation_config.prompt:
                    return jsonify({'error': 'A szöveg prompt szükséges'}), 400

                # Párhuzamos generálás mindkét modellel
                tasks = [
                    self.google_generator.generate_image(generation_config),
                    self.replicate_generator.generate_flux_image(generation_config)
                ]

                results = await asyncio.gather(*tasks, return_exceptions=True)

                combined_results = []
                for result in results:
                    if isinstance(result, Exception):
                        combined_results.append({
                            'success': False,
                            'error': str(result),
                            'model': 'Unknown'
                        })
                    else:
                        combined_results.append(result)

                return jsonify({
                    'success': True,
                    'prompt': generation_config.prompt,
                    'results': combined_results,
                    'generation_time': datetime.now().isoformat()
                })

            except Exception as e:
                logger.error(f"Combined endpoint hiba: {str(e)}")
                return jsonify({'error': f'Szerver hiba: {str(e)}'}), 500

        @self.app.route('/download')
        def download_image():
            try:
                image_url = request.args.get('url')
                if not image_url:
                    return "Nincs kép URL megadva", 400

                # Base64 adatok kezelése
                if image_url.startswith('data:image'):
                    # Base64 kép dekódolása
                    header, encoded = image_url.split(',', 1)
                    image_data = base64.b64decode(encoded)
                    img_io = BytesIO(image_data)
                else:
                    # URL-ből letöltés
                    response = requests.get(image_url, timeout=30)
                    response.raise_for_status()
                    img_io = BytesIO(response.content)

                img_io.seek(0)
                filename = f"generated_image_{uuid.uuid4().hex[:8]}.png"

                return send_file(
                    img_io,
                    mimetype='image/png',
                    as_attachment=True,
                    download_name=filename
                )

            except Exception as e:
                logger.error(f"Download hiba: {str(e)}")
                return f"Hiba a kép letöltésekor: {str(e)}", 500

        @self.app.route('/health')
        def health_check():
            """Egészségügyi ellenőrzés endpoint"""
            return jsonify({
                'status': 'healthy',
                'timestamp': datetime.now().isoformat(),
                'version': '2.0.0'
            })

# Alkalmazás példány létrehozása
def create_app():
    """Alkalmazás factory függvény"""
    try:
        app_instance = ImageGeneratorApp()
        logger.info("Alkalmazás sikeresen inicializálva")
        return app_instance.app
    except Exception as e:
        logger.error(f"Alkalmazás inicializálás hiba: {str(e)}")
        raise

if __name__ == '__main__':
    app = create_app()

    # Fejlesztői mód beállítása
    debug_mode = os.environ.get('FLASK_DEBUG', 'False').lower() == 'true'
    port = int(os.environ.get('PORT', 5000))

    logger.info(f"Alkalmazás indítása - Debug: {debug_mode}, Port: {port}")

    app.run(
        host='0.0.0.0',
        port=port,
        debug=debug_mode,
        threaded=True
    )


