                    this.handleFluxGeneration();
                });

                document.getElementById('combined-form')?.addEventListener('submit', (e) => {
                    e.preventDefault();
                    this.handleCombinedGeneration();
                });
            }

            async handleImagenGeneration() {
                if (this.isGenerating) return;

                const formData = this.getImagenFormData();
                if (!formData.prompt.trim()) {
                    this.showError('A szöveg prompt megadása kötelező');
                    return;
                }

                await this.generateWithErrorHandling('generate_imagen', formData);
            }

            async handleFluxGeneration() {
                if (this.isGenerating) return;

                const formData = this.getFluxFormData();
                if (!formData.prompt.trim()) {
                    this.showError('A szöveg prompt megadása kötelező');
                    return;
                }

                await this.generateWithErrorHandling('generate_flux', formData);
            }

            async handleCombinedGeneration() {
                if (this.isGenerating) return;

                const formData = this.getCombinedFormData();
                if (!formData.prompt.trim()) {
                    this.showError('A szöveg prompt megadása kötelező');
                    return;
                }

                await this.generateWithErrorHandling('generate_combined', formData);
            }

            async generateWithErrorHandling(endpoint, formData) {
                try {
                    this.isGenerating = true;
                    this.showLoading();

                    const response = await fetch(`/${endpoint}`, {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json',
                        },
                        body: JSON.stringify(formData)
                    });

                    const data = await response.json();

                    if (response.ok && data.success) {
                        this.showResult(data, endpoint);
                    } else {
                        this.showError(data.error || 'Ismeretlen hiba történt');
                    }
                } catch (error) {
                    this.showError(`Hálózati hiba: ${error.message}`);
                } finally {
                    this.isGenerating = false;
                }
            }

            getImagenFormData() {
                return {
                    prompt: document.getElementById('imagen-prompt').value,
                    aspect_ratio: document.getElementById('imagen-aspect-ratio').value,
                    safety_filter_level: document.getElementById('imagen-safety').value,
                    output_format: 'png'
                };
            }

            getFluxFormData() {
                const formData = {
                    prompt: document.getElementById('flux-prompt').value,
                    aspect_ratio: document.getElementById('flux-aspect-ratio').value,
                    finetune_id: document.getElementById('flux-finetune-id').value,
                    finetune_strength: parseFloat(document.getElementById('flux-finetune-strength').value),
                    safety_tolerance: parseInt(document.getElementById('flux-safety').value)
                };

                const seed = document.getElementById('flux-seed').value;
                if (seed) {
                    formData.seed = parseInt(seed);
                }

                return formData;
            }

            getCombinedFormData() {
                return {
                    prompt: document.getElementById('combined-prompt').value,
                    aspect_ratio: document.getElementById('combined-aspect-ratio').value
                };
            }

            showLoading(message = 'AI képgenerálás folyamatban...') {
                document.getElementById('results').innerHTML = `
                    <div class="loading">
                        <div class="spinner"></div>
                        <p>${message}</p>
                        <small>Kérjük várjon, ez eltarthat néhány másodpercig</small>
                    </div>
                `;
            }

            showError(message) {
                document.getElementById('results').innerHTML = `
                    <div class="error-message">
                        <h4>⚠️ Hiba történt</h4>
                        <p>${message}</p>
                        <small>Kérjük próbálja újra később</small>
                    </div>
                `;
            }

            showResult(data, endpoint) {
                const resultsDiv = document.getElementById('results');

                if (endpoint === 'generate_combined') {
                    this.renderCombinedResults(data, resultsDiv);
                } else {
                    this.renderSingleResult(data, resultsDiv);
                }
            }

            renderSingleResult(data, container) {
                container.innerHTML = `
                    <div class="result-item">
                        <div class="result-header">
                            <span class="model-name">✨ ${data.model}</span>
                            <button onclick="downloadImage('${data.image_url}')" class="download-btn">
                                📥 Letöltés
                            </button>
                        </div>
                        <img src="${data.image_url}" alt="Generált kép" class="result-image" loading="lazy">
                        <div class="result-meta">
                            <p><strong>Prompt:</strong> ${data.prompt}</p>
                            <small>Generálva: ${new Date(data.generation_time).toLocaleString('hu-HU')}</small>
                        </div>
                    </div>
                `;
            }

            renderCombinedResults(data, container) {
                let html = '<div class="result-item"><h3>🎨 Generált képek mindkét AI modellel:</h3>';

                data.results.forEach(result => {
                    if (result.success) {
                        html += `
                            <div class="result-header">
                                <span class="model-name">✨ ${result.model}</span>
                                <button onclick="downloadImage('${result.image_url}')" class="download-btn">
                                    📥 Letöltés
                                </button>
                            </div>
                            <img src="${result.image_url}" alt="Generált kép - ${result.model}" class="result-image" loading="lazy">
                        `;
                    } else {
                        html += `
                            <div class="result-header">
                                <span class="model-name">❌ ${result.model}</span>
                            </div>
                            <div class="error-message">Hiba: ${result.error}</div>
                        `;
                    }
                });

                html += `
                    <div class="result-meta">
                        <p><strong>Prompt:</strong> ${data.prompt}</p>
                        <small>Generálva: ${new Date(data.generation_time).toLocaleString('hu-HU')}</small>
                    </div>
                </div>`;

                container.innerHTML = html;
            }
        }

        // Globális függvények
        function downloadImage(imageUrl) {
            const link = document.createElement('a');
            link.href = `/download?url=${encodeURIComponent(imageUrl)}`;
            link.download = `ai_generated_${Date.now()}.png`;
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
        }

        function openBetaMenu() {
            const overlay = document.getElementById('beta-overlay');
            const mainContent = document.getElementById('main-content');

            mainContent.classList.add('hidden');

            setTimeout(() => {
                overlay.classList.add('active');
            }, 200);
        }

        function closeBetaMenu() {
            const overlay = document.getElementById('beta-overlay');
            const mainContent = document.getElementById('main-content');

            overlay.classList.remove('active');

            setTimeout(() => {
                mainContent.classList.remove('hidden');
            }, 300);
        }

        function showImageGenerator() {
            const mainContent = document.getElementById('main-content');
            closeBetaMenu();

            setTimeout(() => {
                mainContent.style.display = 'block';
                mainContent.classList.remove('hidden');
            }, 500);
        }

        function showTab(tabName) {
            document.querySelectorAll('.tab-content').forEach(tab => {
                tab.classList.remove('active');
            });
            document.querySelectorAll('.tab').forEach(tab => {
                tab.classList.remove('active');
            });

            document.getElementById(tabName + '-tab').classList.add('active');
            event.target.classList.add('active');
        }

        // Alkalmazás inicializálása
        document.addEventListener('DOMContentLoaded', () => {
            new AIImageGenerator();
            console.log('🚀 AI Képgeneráló Platform inicializálva');
        });
    </script>
</body>
</html>


